     * Returns the context's unique identifier.
     */
    fun `contextId`(): kotlin.String
    
    /**
     * Returns the DID of the context creator.
     */
    fun `creatorDid`(): kotlin.String
    
    /**
     * Returns the context's current lifecycle state as a string.
     *
