/**
 * @suppress
 */
public object FfiConverterTypeContextHandle: FfiConverter<ContextHandle, Pointer> {

    override fun lower(value: ContextHandle): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): ContextHandle {
        return ContextHandle(value)
    }

    override fun read(buf: ByteBuffer): ContextHandle {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: ContextHandle) = 8UL

    override fun write(value: ContextHandle, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}


