public object FfiConverterTypeContextState: FfiConverterRustBuffer<ContextState> {
    override fun read(buf: ByteBuffer) = try {
        ContextState.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: ContextState) = 4UL

    override fun write(value: ContextState, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
