/**
 * How the data source was discovered by the receiving party (spec §24.2.3).
 */
sealed class DiscoveryMethod {
    
    /**
     * Source was discovered through shared membership in the given context.
     */
    data class SharedContext(
        val `contextId`: kotlin.String) : DiscoveryMethod() {
        companion object
    }
    
    /**
     * Source was discovered through a discovery registry context.
     */
    data class Registry(
        val `contextId`: kotlin.String) : DiscoveryMethod() {
        companion object
    }
    
    /**
     * No protocol-level discovery path (out-of-band introduction).
     */
    object OutOfBand : DiscoveryMethod()
    
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeDiscoveryMethod : FfiConverterRustBuffer<DiscoveryMethod>{
    override fun read(buf: ByteBuffer): DiscoveryMethod {
        return when(buf.getInt()) {
            1 -> DiscoveryMethod.SharedContext(
                FfiConverterString.read(buf),
                )
            2 -> DiscoveryMethod.Registry(
                FfiConverterString.read(buf),
                )
            3 -> DiscoveryMethod.OutOfBand
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: DiscoveryMethod) = when(value) {
        is DiscoveryMethod.SharedContext -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`contextId`)
            )
        }
        is DiscoveryMethod.Registry -> {
